#!/usr/bin/env python3
"""Decode campaign captures into typed logical records."""
import csv
import io

import zstandard as zstd

from common import COLUMNS, CaptureError, decode64
from ledger import parse_record

DECODED_BUDGET = 32 * 1024 ** 2
STREAM_BUDGET = 128 * 1024 ** 2
RECORD_BUDGET = 200000
FIELD_BUDGET = 131072
FIELD_ASCII = FIELD_BUDGET // 4
FIELD_LIMIT = 1 << 27
MAGIC = 0xfd2fb528
SKIPPABLE_LO = 0x184d2a50
SKIPPABLE_HI = 0x184d2a5f
WINDOW_LIMIT = 128 * 1024 ** 2
READ_BLOCK = 1 << 20


def check_frames(data):
    """Validate complete dictionary-free bounded-window Zstandard framing."""
    at = 0
    size = len(data)
    while at < size:
        if at + 4 > size:
            raise CaptureError('truncated Zstandard magic')
        magic = int.from_bytes(data[at:at + 4], 'little')
        if SKIPPABLE_LO <= magic <= SKIPPABLE_HI:
            if at + 8 > size:
                raise CaptureError('truncated skippable frame')
            skip = int.from_bytes(data[at + 4:at + 8], 'little')
            at += 8 + skip
            if at > size:
                raise CaptureError('truncated skippable frame')
            continue
        if magic != MAGIC:
            raise CaptureError('invalid Zstandard magic')
        if at + 5 > size:
            raise CaptureError('truncated Zstandard header')
        flag = data[at + 4]
        if flag & 0x08:
            raise CaptureError('reserved Zstandard frame bit')
        single = bool(flag & 0x20)
        dictionary = (0, 1, 2, 4)[flag & 3]
        content = (1 if single else 0, 2, 4, 8)[flag >> 6]
        header = 5 + (0 if single else 1) + dictionary + content
        if at + header > size:
            raise CaptureError('truncated Zstandard header')
        params = zstd.get_frame_parameters(data[at:at + header])
        if params.dict_id or params.window_size > WINDOW_LIMIT:
            raise CaptureError('unsupported dictionary or window')
        at += header
        while True:
            if at + 3 > size:
                raise CaptureError('truncated Zstandard block')
            block = int.from_bytes(data[at:at + 3], 'little')
            at += 3
            kind = (block >> 1) & 3
            if kind == 3:
                raise CaptureError('reserved Zstandard block type')
            at += 1 if kind == 1 else block >> 3
            if at > size:
                raise CaptureError('truncated Zstandard block')
            if block & 1:
                break
        if flag & 4:
            at += 4
            if at > size:
                raise CaptureError('truncated Zstandard checksum')
    return True


def inflate(data, budget):
    """Decompress every concatenated/skippable frame within a byte budget."""
    out = bytearray()
    reader = zstd.ZstdDecompressor().stream_reader(io.BytesIO(data), read_across_frames=True)
    try:
        while True:
            block = reader.read(READ_BLOCK)
            if not block:
                break
            out += block
            if len(out) > budget:
                raise CaptureError('decompressed byte budget')
    finally:
        reader.close()
    return bytes(out)


def _fields_ok(values):
    for value in values:
        length = len(value)
        if length > FIELD_BUDGET:
            return False
        if length > FIELD_ASCII and not value.isascii() and len(value.encode('utf-8')) > FIELD_BUDGET:
            return False
    return True


def capture_records(context, probes):
    """Read every capture and return (records, rejected indices)."""
    csv.field_size_limit(FIELD_LIMIT)
    leases = context['leases']
    services = context['services']
    records = []
    rejected = []
    decoded = 0
    stream = 0
    count = 0
    for number, capture in enumerate(context['captures']):
        text, decoded, stream = _transport(capture, decoded, stream)
        rows = _rows(text)
        del text
        ordinal = 0
        try:
            header = next(rows, None)
            if header != list(COLUMNS):
                raise CaptureError('invalid CSV header')
            for values in rows:
                count += 1
                if count > RECORD_BUDGET or not _fields_ok(values):
                    raise CaptureError('capture record budget')
                try:
                    records.append(parse_record(values, leases, services, probes))
                except (ValueError, TypeError, KeyError, IndexError):
                    rejected.append([number, ordinal])
                ordinal += 1
        except csv.Error as exc:
            raise CaptureError('invalid capture CSV') from exc
    return records, rejected


def _transport(capture, decoded, stream):
    """Decode, inflate and UTF-8 decode one capture.

    Returns the CSV text plus the running decoded and decompressed totals.
    """
    blocks = []
    for chunk in capture['chunks']:
        block = decode64(chunk, CaptureError)
        decoded += len(block)
        if decoded > DECODED_BUDGET:
            raise CaptureError('decoded byte budget')
        blocks.append(block)
    data = b''.join(blocks)
    del blocks
    try:
        if capture['encoding'] == 'zstd':
            check_frames(data)
            if stream >= STREAM_BUDGET:
                raise CaptureError('decompressed byte budget')
            data = inflate(data, STREAM_BUDGET - stream)
        elif len(data) > STREAM_BUDGET - stream:
            raise CaptureError('decompressed byte budget')
        return data.decode('utf-8'), decoded, stream + len(data)
    except CaptureError:
        raise
    except Exception as exc:
        raise CaptureError('invalid capture transport') from exc


def _rows(text):
    return csv.reader(io.StringIO(text, newline=''), strict=True)


def main() -> None:
    """Legacy development helper: bucket ZMap6 responses by /64 network."""
    import argparse
    import ipaddress
    import json

    parser = argparse.ArgumentParser(description='group ZMap6 responses by /64 network')
    parser.add_argument('aliases_file', help='aliased /64 prefixes (4 colon groups)')
    parser.add_argument('zmap_csv', help='ZMap6 output CSV.zst')
    args = parser.parse_args()

    aliases = set()
    with open(args.aliases_file) as handle:
        for line in handle:
            aliases.add(line.strip())
    networks = {}
    with open(args.zmap_csv, 'rb') as handle:
        reader = zstd.ZstdDecompressor().stream_reader(handle, read_across_frames=True)
        text = io.TextIOWrapper(reader, encoding='utf-8', newline='')
        for line in text:
            if line.startswith('saddr'):
                continue
            fields = line.rstrip('\r\n').split(',')
            if len(fields) < 2:
                continue
            target, responder = fields[0], fields[1]
            try:
                exploded = ipaddress.IPv6Address(target).exploded
            except ipaddress.AddressValueError:
                continue
            net64 = ':'.join(exploded.split(':')[:4])
            if net64 in aliases:
                continue
            bucket = networks.setdefault(net64, {'network': net64, 'internal': set(),
                                                 'external': set()})
            if target == responder:
                bucket['internal'].add(responder)
            else:
                bucket['external'].add(responder)
    for entry in networks.values():
        entry['internal'] = sorted(entry['internal'])
        entry['external'] = sorted(entry['external'])
        print(json.dumps(entry))


if __name__ == '__main__':
    main()
